<template><q-card flat bordered class="ubi-filtros q-mb-lg q-pa-md"><div class="row q-col-gutter-md items-end"><div class="col-12 col-md-6"><q-input v-model.trim="local.texto" outlined dense clearable label="Buscar ubicación" placeholder="Código o nombre..." color="green-8" @keyup.enter="emitir"><template #prepend><q-icon name="search" color="green-8"/></template></q-input></div><div class="col-12 col-sm-6 col-md-2"><q-select v-model="local.almacen" :options="almacenes" outlined dense clearable emit-value map-options label="Almacén" color="green-8"/></div><div class="col-12 col-sm-6 col-md-2"><q-select v-model="local.tipo" :options="tipos" outlined dense clearable emit-value map-options label="Tipo" color="green-8"/></div><div class="col-12 col-sm-6 col-md-2"><q-select v-model="local.estado" :options="estados" outlined dense clearable emit-value map-options label="Estado" color="green-8"/></div><div class="col-12 row justify-end q-gutter-sm q-mt-sm"><q-btn flat no-caps color="green-8" icon="clear" label="Limpiar" @click="limpiar"/><q-btn unelevated no-caps color="green-8" icon="search" label="Buscar" @click="emitir"/></div></div></q-card></template>
<script setup>
import { computed, reactive, watch } from 'vue'
const props=defineProps({almacenInicial:{type:String,default:null},almacenes:{type:Array,default:()=>[]},tipos:{type:Array,default:()=>[]},estados:{type:Array,default:()=>[]}});const emit=defineEmits(['filtrar','limpiar']);const local=reactive({texto:'',almacen:null,tipo:null,estado:null});let limpiando=false;watch(()=>props.almacenInicial,v=>{local.almacen=v||null},{immediate:true});watch(()=>local.texto,()=>{if(!limpiando) emitir()});const opciones=items=>[{label:'Todos',value:null},...items];const almacenes=computed(()=>opciones(props.almacenes));const tipos=computed(()=>opciones(props.tipos));const estados=computed(()=>opciones(props.estados));function emitir(){emit('filtrar',{...local})}function limpiar(){limpiando=true;Object.assign(local,{texto:'',almacen:null,tipo:null,estado:null});emit('limpiar');queueMicrotask(()=>{limpiando=false})}
</script>
<style scoped>.ubi-filtros{border-radius:12px;border-color:#e5e7eb!important;box-shadow:0 3px 16px rgba(74,140,37,.06)}:deep(.q-field__control){border:1.5px solid #4a8c25;border-radius:8px;box-shadow:none}@media(max-width:599px){.ubi-filtros{padding:14px}.ubi-filtros .q-btn{min-height:44px}}
</style>
